mercial de Intenso. Precio consultado el 13/10/2026; confirma el importe y la disponibilidad actuales en PcComponentes.","specifications":[{"label":"Capacidad","value":"2000 GB"},{"label":"Interfaz","value":"PCI Express 3.0 NVMe"},{"label":"Formato","value":"M.2 2280"},{"label":"Lectura secuencial","value":"2100 MB/s"},{"label":"Escritura secuencial","value":"1700 MB/s"}],"sourceSpecifications":{"capacidad":"2000 GB","interfaz":"PCI Express 3.0 NVMe","formato":"M.2 2280","lectura":"2100 MB/s","escritura":"1700 MB/s"},"pcBuilder":{"category":"storage","capacity_tb":2,"interface":"NVMe PCIe 3.0"}},{"id":"ref-storage-fo-ssd-n-1tb-6","slug":"forgeon-nimbus-disco-ssd-1tb-6400-mb-s-nvme-pcie-4-0-m-2-2280-0aa04","sku":"REF-FOSSDN1TB6-0AA04","name":"Forgeon Nimbus Disco SSD 1TB 6400 MB/s NVMe PCIe 4.0 M.2 2280","brand":"Forgeon","modelNumber":"FO-SSD-N-1TB-6","category":"storage","rootCategory":"Almacenamiento","categorySlug":"ssd-internos","priceEur":172.95,"productUrl":"https://www.pccomponentes.com/disco-duro-forgeon-nimbus-disco-ssd-1tb-6400-mb-s-nvme-pcie-4-0-m-2-2280","imageUrl":"https://img.pccomponentes.com/articles/1101/11016171/1128-forgeon-nimbus-disco-ssd-1tb-6400-mb-s-nvme-pcie-40-m2-2280.jpg","imageAlt":"Forgeon Nimbus Disco SSD 1TB 6400 MB/s NVMe PCIe 4.0 M.2 2280","checkedAt":"2026-10-13","source":"PcComponentes","seller":"PcComponentes","summary":"Referencia comercial de Forgeon. Precio consultado el 13/10/2026; confirma el importe y la disponibilidad actuales en PcComponentes.","specifications":[{"label":"Capacidad","value":"1 TB"},{"label":"Interfaz","value":"PCIe Gen4 NVMe 1.4"},{"label":"Formato","value":"M.2 2280"},{"label":"Lectura secuencial","value":"6400 MB/s"},{"label":"Escritura secuencial","value":"5000 MB/s"}],"sourceSpecifications":{"capacidad":"1 TB","interfaz":"PCIe Gen4 NVMe 1.4","formato":"M.2 2280","lectura":"6400 MB/s","escritura":"5000 MB/s"},"pcBuilder":{"category":"storage","capacity_tb":1,"interface":"NVMe PCIe 4.0"}},{"id":"ref-storage-wds400t1r0c","slug":"wd-red-sn700-4tb-ssd-m-2-nvme-pcie-3-0-0v1uy","sku":"REF-WDS400T1R0C-0V1UY","name":"WD Red SN700 4TB SSD M.2 NVMe PCIe 3.0","brand":"Sandisk","modelNumber":"WDS400T1R0C","category":"storage","rootCategory":"Almacenamiento","categorySlug":"ssd-internos","priceEur":1089,"productUrl":"https://www.pccomponentes.com/disco-duro-wd-red-sn700-4tb-ssd-m-2-nvme-pcie-3-0","imageUrl":"https://img.pccomponentes.com/articles/1000/10000797/1625-wd-red-sn700-4tb-ssd-m2-nvme-pcie-30-foto.jpg","imageAlt":"WD Red SN700 4TB SSD M.2 NVMe PCIe 3.0","checkedAt":"2026-10-13","source":"PcComponentes","seller":"PcComponentes","summary":"Referencia comercial de Sandisk. Precio consultado el 13/10/2026; confirma el importe y la disponibilidad actuales en PcComponentes.","specifications":[{"label":"Capacidad","value":"4000 GB"},{"label":"Interfaz","value":"PCI Express 3.0 x4 NVMe"},{"label":"Formato","value":"M.2 2280"},{"label":"Lectura secuencial","value":"3400 MB/s"},{"label":"Escritura secuencial","value":"3100 MB/s"}],"sourceSpecifications":{"capacidad":"4000 GB","interfaz":"PCI Express 3.0 x4 NVMe","formato":"M.2 2280","lectura":"3400 MB/s","escritura":"3100 MB/s"},"pcBuilder":{"category":"storage","capacity_tb":4,"interface":"NVMe PCIe 3.0"}},{"id":"ref-storage-aleg-710-256gcs","slug":"adata-legend-710-256gb-ssd-m-2-nvme-nand-gen3x4-04xdr","sku":"REF-ALEG710256GCS-04XDR","name":"Adata Legend 710 256GB SSD M.2 NVMe NAND Gen3x4","brand":"Adata","modelNumber":"ALEG-710-256GCS","category":"storage","rootCategory":"Almacenamiento","categorySlug":"ssd-internos","priceEur":93.25,"productUrl":"https://www.pccomponentes.com/disco-duro-adata-legend-710-256gb-ssd-m-2-nvme-nand-gen3x4","imageUrl":"https://img.pccomponentes.com/articles/1084/10847934/142-adata-legend-710-256gb-ssd-m2-nvme-nand-gen3x4.jpg","imageAlt":"Adata Legend 710 256GB SSD M.2 NVMe NAND Gen3x4","checkedAt":"2026-10-13","source":"PcComponentes","seller":"PcComponentes","summary":"Referencia comercial de Adata. Precio consultado el 13/10/2026; confirma el importe y la disponibilidad actuales en PcComponentes.","specifications":[{"label":"Capacidad","value":"256 GB"},{"label":"Interfaz","value":"PCI Express 3.0 NVMe"},{"label":"Formato","value":"M.2"},{"label":"Lectura secuencial","value":"2100 MB/s"},{"label":"Escritura secuencial","value":"1000 MB/s"}],"sourceSpecifications":{"capacidad":"256 GB","interfaz":"PCI Express 3.0 NVMe","formato":"M.2","lectura":"2100 MB/s","escritura":"1000 MB/s"},"pcBuilder":{"category":"storage","capacity_tb":0.256,"interface":"NVMe PCIe 3.0"}},{"id":"ref-storage-mz-v9p1t0bw","slug":"samsung-990-pro-1tb-disco-ssd-7450mb-s-nvme-pcie-4-0-m-2-gen4-1vopo","sku":"REF-MZV9P1T0BW-1VOPO","name":"Samsung 990 Pro 1TB Disco SSD 7450MB/S NVMe PCIe 4.0 M.2 Gen4","brand":"Samsung","modelNumber":"MZ-V9P1T0BW","category":"storage","rootCategory":"Almacenamiento","categorySlug":"ssd-internos","priceEur":218.99,"productUrl":"https://www.pccomponentes.com/disco-duro-samsung-990-pro-1tb-disco-ssd-7450mb-s-nvme-pcie-4-0-m-2-gen4","imageUrl":"https://img.pccomponentes.com/articles/1064/10648533/1721-samsung-990-pro-1tb-ssd-pcie-40-nvme-m2.jpg","imageAlt":"Samsung 990 Pro 1TB Disco SSD 7450MB/S NVMe PCIe 4.0 M.2 Gen4","checkedAt":"2026-10-13","source":"PcComponentes","seller":"PcComponentes","summary":"Referencia comercial de Samsung. Precio consultado el 13/10/2026; confirma el importe y la disponibilidad actuales en PcComponentes.","specifications":[{"label":"Capacidad","value":"1000 GB"},{"label":"Interfaz","value":"PCIe Gen 4.0 x4, NVMe 2.0"},{"label":"Formato","value":"M.2 2280"},{"label":"Lectura secuencial","value":"hasta 7450 MB/s"},{"label":"Escritura secuencial","value":"hasta 6900 MB/s"}],"sourceSpecifications":{"capacidad":"1000 GB","interfaz":"PCIe Gen 4.0 x4, NVMe 2.0","formato":"M.2 2280","lectura":"hasta 7450 MB/s","escritura":"hasta 6900 MB/s"},"pcBuilder":{"category":"storage","capacity_tb":1,"interface":"NVMe PCIe 4.0"}},{"id":"ref-storage-snv3sm3-1t0","slug":"ssd-kingston-nv3-1tb-m-2-2230-pcie-4-0-nvme-6000mb-s-3d-nand-gaming-0ete5","sku":"REF-SNV3SM31T0-0ETE5","name":"SSD Kingston NV3 1TB M.2 2230 PCIe 4.0 NVMe 6000MB/s 3D NAND Gaming","brand":"Kingston","modelNumber":"SNV3SM3/1T0","category":"storage","rootCategory":"Almacenamiento","categorySlug":"ssd-internos","priceEur":269.73,"productUrl":"https://www.pccomponentes.com/disco-duro-ssd-kingston-nv3-1tb-m-2-2230-pcie-4-0-nvme-6000mb-s-3d-nand-gaming","imageUrl":"https://img.pccomponentes.com/articles/1093/10932024/1572-ssd-kingston-nv3-1tb-m2-2230-pcie-40-nvme-6000mb-s-3d-nand-gaming.jpg","imageAlt":"SSD Kingston NV3 1TB M.2 2230 PCIe 4.0 NVMe 6000MB/s 3D NAND Gaming","checkedAt":"2026-10-13","source":"PcComponentes","seller":"PcComponentes","summary":"Referencia comercial de Kingston. Precio consultado el 13/10/2026; confirma el importe y la disponibilidad actuales en PcComponentes.","specifications":[{"label":"Capacidad","value":"1 TB"},{"label":"Interfaz","value":"PCI Express 4.0 x4 (NVMe)"},{"label":"Formato","value":"M.2 2230"},{"label":"Lectura secuencial","value":"6000 MB/s"},{"label":"Escritura secuencial","value":"4000 MB/s"}],"sourceSpecifications":{"capacidad":"1 TB","interfaz":"PCI Express 4.0 x4 (NVMe)","formato":"M.2 2230","lectura":"6000 MB/s","escritura":"4000 MB/s"},"pcBuilder":{"category":"storage","capacity_tb":1,"interface":"NVMe PCIe 4.0"}},{"id":"ref-storage-3835450","slug":"intenso-premium-ssd-500gb-m-2-nvme-pcie-3-0-1pl6c","sku":"REF-3835450-1PL6C","name":"Intenso Premium SSD 500GB M.2 NVMe PCIe 3.0","brand":"Intenso","modelNumber":"3835450","category":"storage","rootCategory":"Almacenamiento","categorySlug":"ssd-internos","priceEur":94.99,"productUrl":"https://www.pccomponentes.com/disco-duro-intenso-premium-ssd-500gb-m-2-nvme-pcie-3-0","imageUrl":"https://img.pccomponentes.com/articles/1073/10735317/1866-intenso-premium-ssd-500gb-m2-nvme-pcie-30-mejor-precio.jpg","imageAlt":"Intenso Premium SSD 500GB M.2 NVMe PCIe 3.0","checkedAt":"2026-10-13","source":"PcComponentes","seller":"PcComponentes","summary":"Referencia comercial de Intenso. Precio consultado el 13/10/2026; confirma el importe y la disponibilidad actuales en PcComponentes.","specifications":[{"label":"Capacidad","value":"500 GB"},{"label":"Interfaz","value":"PCI Express 3.0 NVMe"},{"label":"Formato","value":"M.2"},{"label":"Lectura secuencial","value":"2100 MB/s"},{"label":"Escritura secuencial","value":"1700 MB/s"}],"sourceSpecifications":{"capacidad":"500 GB","interfaz":"PCI Express 3.0 NVMe","formato":"M.2","lectura":"2100 MB/s","escritura":"1700 MB/s"},"pcBuilder":{"category":"storage","capacity_tb":0.5,"interface":"NVMe PCIe 3.0"}}]$catalog$::jsonb;
  v_row record;
  v_spec jsonb;
  v_spec_index integer;
  v_root_id uuid;
  v_leaf_id uuid;
  v_stock record;
begin
  create temporary table _verified_reference_products on commit drop as
  select *
  from jsonb_to_recordset(v_catalog) as item(
    id text, slug text, sku text, name text, brand text, "modelNumber" text,
    category text, "rootCategory" text, "categorySlug" text, "priceEur" numeric,
    "productUrl" text, "imageUrl" text, "imageAlt" text, "checkedAt" text,
    source text, seller text, summary text, specifications jsonb,
    "sourceSpecifications" jsonb, "pcBuilder" jsonb
  );

  if (select count(*) from _verified_reference_products) <> 64 then
    raise exception 'Expected 64 verified reference products';
  end if;
  if exists (
    select 1 from _verified_reference_products
    where "checkedAt" <> '2026-10-13'
       or source <> 'PcComponentes' or seller <> 'PcComponentes'
       or "productUrl" !~ '^https://www\.pccomponentes\.com/'
       or "imageUrl" !~ '^https://(img|thumb)\.pccomponentes\.com/.*articles/'
       or "priceEur" <= 0
       or "modelNumber" is null or btrim("modelNumber") = ''
  ) then
    raise exception 'Reference catalog contains an unverified source, URL, image, price or model number';
  end if;
  if exists (
    select "categorySlug" from _verified_reference_products
    group by "categorySlug" having count(*) <> 8
  ) or (select count(distinct "categorySlug") from _verified_reference_products) <> 8 then
    raise exception 'Reference catalog must contain exactly eight options in each of the eight component categories';
  end if;

  if exists (
    select 1
    from public.products existing
    join _verified_reference_products incoming
      on existing.id <> incoming.id
     and (existing.slug = incoming.slug or existing.sku = incoming.sku)
  ) then
    raise exception 'A verified reference product conflicts with an existing product id, slug or SKU';
  end if;
  if exists (
    select 1
    from public.product_variants existing
    join _verified_reference_products incoming on existing.sku = incoming.sku
    join public.products owner_product on owner_product.id = existing.product_id
    where existing.product_id <> incoming.id
  ) then
    raise exception 'A verified reference variant SKU belongs to a different existing product';
  end if;

  if exists (
    select 1 from unnest(array[
      'componentes','almacenamiento','procesadores','placas-base','memoria-ram',
      'cajas','fuentes-alimentacion','tarjetas-graficas','refrigeracion','ssd-internos'
    ]) required(slug)
    where not exists(select 1 from public.categories c where c.slug = required.slug)
  ) then
    raise exception 'Expected reference catalog categories are missing; apply the prior catalog category migration first';
  end if;

  update public.categories set description = case slug
    when 'componentes' then 'Referencias de componentes de PC con modelos, imágenes y precios consultados en PcComponentes.'
    when 'almacenamiento' then 'Referencias de almacenamiento con modelos, imágenes y precios consultados en PcComponentes.'
    when 'procesadores' then 'Procesadores de fabricantes reales; verifica socket y datos técnicos en la ficha del vendedor.'
    when 'placas-base' then 'Placas base de fabricantes reales; confirma compatibilidad con cada componente.'
    when 'memoria-ram' then 'Módulos de memoria con modelo, imagen y precio de referencia.'
    when 'cajas' then 'Cajas de PC con imagen de referencia; verifica dimensiones y formatos publicados.'
    when 'fuentes-alimentacion' then 'Fuentes de alimentación de fabricantes reales; revisa capacidad y certificación en su ficha.'
    when 'tarjetas-graficas' then 'Tarjetas gráficas de fabricantes reales; confirma dimensiones, conectores y potencia.'
    when 'refrigeracion' then 'Disipadores y refrigeración con modelos de referencia; confirma compatibilidad de socket.'
    when 'ssd-internos' then 'Unidades SSD reales con imagen y precio consultados en PcComponentes.'
    else description end,
    updated_at = now()
  where slug in (
    'componentes','almacenamiento','procesadores','placas-base','memoria-ram',
    'cajas','fuentes-alimentacion','tarjetas-graficas','refrigeracion','ssd-internos'
  );

  -- Retire only known generated demo records; keep them unpublished for historic order references.
  for v_stock in
    select i.warehouse_id, i.variant_id, i.on_hand, i.reserved
    from public.inventory i
    join public.product_variants v on v.id = i.variant_id
    join public.products p on p.id = v.product_id
    where (p.id like 'pr_depth_%' or p.id like 'pr_nodria_%'
       or p.id in ('pr_fluxbook14','pr_foundry_s','pr_loom27','pr_linkmesh','pr_slateair','pr_arcssd')
       or p.sku like 'NOD-%' or p.image_url ilike '%images.unsplash.com%')
      and i.on_hand > i.reserved
  loop
    perform private.adjust_inventory(
      v_stock.warehouse_id, v_stock.variant_id,
      v_stock.reserved - v_stock.on_hand,
      'Retirada de inventario sintético al publicar referencias externas verificadas'
    );
  end loop;

  update public.product_variants variant
     set is_active = false, updated_at = now()
   where variant.product_id in (
     select product.id from public.products product
     where product.id like 'pr_depth_%' or product.id like 'pr_nodria_%'
        or product.id in ('pr_fluxbook14','pr_foundry_s','pr_loom27','pr_linkmesh','pr_slateair','pr_arcssd')
        or product.sku like 'NOD-%' or product.image_url ilike '%images.unsplash.com%'
   );

  update public.products product
     set is_published = false,
         is_featured = false,
         badge = null,
         rating_average = 0,
         rating_count = 0,
         updated_at = now()
   where product.id like 'pr_depth_%' or product.id like 'pr_nodria_%'
      or product.id in ('pr_fluxbook14','pr_foundry_s','pr_loom27','pr_linkmesh','pr_slateair','pr_arcssd')
      or product.sku like 'NOD-%' or product.image_url ilike '%images.unsplash.com%';

  for v_row in select * from _verified_reference_products order by name loop
    select c.id into v_root_id from public.categories c where c.slug =
      case when v_row."rootCategory" = 'Almacenamiento' then 'almacenamiento' else 'componentes' end;
    select c.id into v_leaf_id from public.categories c where c.slug = v_row."categorySlug";

    insert into public.products (
      id, slug, sku, name, brand, summary, description, image_url, image_alt, badge,
      rating_average, rating_count, is_featured, is_published, published_at
    ) values (
      v_row.id, v_row.slug, v_row.sku, v_row.name, v_row.brand,
      v_row.summary,
      v_row.name || ' (' || v_row."modelNumber" || '). Precio observado: ' ||
        to_char(v_row."priceEur", 'FM999999990.00') || ' EUR el ' ||
        to_char(v_row."checkedAt"::date, 'DD/MM/YYYY') ||
        '. Ficha e imagen del modelo publicadas por PcComponentes. NODRIA no vende este producto; confirma condiciones, disponibilidad y precio vigente con el vendedor.',
      v_row."imageUrl", v_row."imageAlt", null, 0, 0,
      (v_row.name = (
        select min(candidate.name) from _verified_reference_products candidate
        where candidate."categorySlug" = v_row."categorySlug"
      )),
      true, now()
    )
    on conflict (id) do update set
      slug = excluded.slug,
      sku = excluded.sku,
      name = excluded.name,
      brand = excluded.brand,
      summary = excluded.summary,
      description = excluded.description,
      image_url = excluded.image_url,
      image_alt = excluded.image_alt,
      badge = null,
      rating_average = 0,
      rating_count = 0,
      is_featured = excluded.is_featured,
      is_published = true,
      published_at = coalesce(public.products.published_at, excluded.published_at),
      updated_at = now();

    insert into public.product_categories(product_id, category_id)
    values (v_row.id, v_root_id), (v_row.id, v_leaf_id)
    on conflict (product_id, category_id) do nothing;

    insert into public.product_variants (
      id, product_id, sku, title, attributes, current_price, compare_at_price, currency, tax_rate, is_active
    ) values (
      (substr(md5('nodria-reference:' || v_row.sku),1,8) || '-' ||
       substr(md5('nodria-reference:' || v_row.sku),9,4) || '-4' ||
       substr(md5('nodria-reference:' || v_row.sku),14,3) || '-8' ||
       substr(md5('nodria-reference:' || v_row.sku),18,3) || '-' ||
       substr(md5('nodria-reference:' || v_row.sku),21,12))::uuid,
      v_row.id, v_row.sku, 'Referencia PcComponentes',
      jsonb_build_object(
        'reference_price', jsonb_build_object(
          'source', v_row.source,
          'seller', v_row.seller,
          'url', v_row."productUrl",
          'observed_at', v_row."checkedAt",
          'price_eur', v_row."priceEur",
          'image_url', v_row."imageUrl",
          'mpn', v_row."modelNumber"
        ),
        'pc_builder', v_row."pcBuilder"
      ),
      v_row."priceEur", null, 'EUR', 0.21, true
    )
    on conflict (sku) do update set
      product_id = excluded.product_id,
      title = excluded.title,
      attributes = excluded.attributes,
      current_price = excluded.current_price,
      compare_at_price = null,
      currency = excluded.currency,
      tax_rate = excluded.tax_rate,
      is_active = true,
      updated_at = now();

    for v_spec_index in 0..jsonb_array_length(v_row.specifications) - 1 loop
      v_spec := v_row.specifications -> v_spec_index;
      insert into public.product_specifications(product_id, label, value, sort_order)
      values (
        v_row.id,
        v_spec ->> 'label',
        v_spec ->> 'value',
        (v_spec_index + 1) * 10
      )
      on conflict (product_id, label) do update set
        value = excluded.value, sort_order = excluded.sort_order;
    end loop;
  end loop;
end
